public class PriceTests
{
    [Fact]
    public void Rejects_negative_price() =>
        Assert.Throws<ArgumentOutOfRangeException>(() => new Price(-1));

    [Theory]
    [InlineData(0, "$0.00")]
    [InlineData(12.5, "$12.50")]
    [InlineData(1000, "$1,000.00")]
    public void Formats_with_two_decimals(decimal value, string expected) =>
        Assert.Equal(expected, new Price(value).ToString());
}

public sealed class DatabaseFixture : IDisposable
{
    public AppDbContext Db { get; } = TestDbContext.Create();

    public void Dispose() => Db.Dispose();
}

public class RepositoryTests(DatabaseFixture fixture)
    : IClassFixture<DatabaseFixture>
{
    [Fact]
    public async Task Saves_an_order() =>
        await new OrderRepository(fixture.Db).AddAsync(Order.Create(Guid.NewGuid(), 10));
